python3 << 'PYEOF'
import json

with open('/home/ubuntu/.claude-account-2/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-7-projects-gen-depth-contamination/1ce3f958-aabe-450c-8fc4-2f2224e19e1f/tool-results/mcp-agent-ml-research-read_registry-1779047878541.txt') as f:
    raw = json.load(f)

data = json.loads(raw['result'])
experiments = data['data']['experiments']

# Collect all experiments with enough pairwise AUC data (>=3 pairs: 0v1, 1v2, 2v3)
# Two formats: nested pairwise_auc dict, or flat auc_XvY / XvY_auc keys

all_exp_data = []

for exp_id, exp in experiments.items():
    if not isinstance(exp, dict) or exp.get('conclusion') != 'success':
        continue

    metrics = exp.get('metrics', {})
    hypothesis = exp.get('hypothesis', '')

    pairwise = {}

    # Format 1: nested pairwise_auc dict
    if 'pairwise_auc' in metrics and isinstance(metrics['pairwise_auc'], dict):
        pairwise.update(metrics['pairwise_auc'])

    # Format 2: flat auc_XvY keys (e.g., auc_0v1)
    for key in metrics:
        if key.startswith('auc_') and 'v' in key:
            pair_key = key.replace('auc_', '')
            if isinstance(metrics[key], (int, float)):
                pairwise[pair_key] = metrics[key]

    # Format 3: flat XvY_auc keys (e.g., 0v1_auc)
    for key in metrics:
        if key.endswith('_auc') and 'v' in key and not key.startswith('auc'):
            pair_key = key.replace('_auc', '')
            if isinstance(metrics[key], (int, float)):
                pairwise[pair_key] = metrics[key]

    # Check minimum 3 pairs
    required = ['0v1', '1v2', '2v3']
    if not all(k in pairwise for k in required):
        continue

    # Determine short name / category
    if 'arXiv' in exp_id or 'arxiv' in exp_id.lower():
        domain = 'arXiv'
    elif 'wiki' in exp_id.lower():
        domain = 'Wikipedia'
    elif 'retrain' in exp_id.lower() or exp_id == 'exp_027':
        domain = 'Retrain-chain'
    else:
        domain = 'C4'

    # Extract model from hypothesis or exp_id
    model = ''
    if 'pythia' in exp_id.lower() or 'Pythia' in hypothesis:
        model = 'Pythia-1.4B'
    elif 'olmo' in exp_id.lower() or 'OLMo' in hypothesis:
        model = 'OLMo-1B'
    elif 'llama' in exp_id.lower() or 'LLaMA' in hypothesis:
        model = 'LLaMA-3.1-8B'
    elif 'mistral' in exp_id.lower() or 'Mistral' in hypothesis:
        model = 'Mistral-7B'
    elif 'qwen' in exp_id.lower() or 'Qwen' in hypothesis:
        if '7b' in exp_id.lower() or '7B' in hypothesis:
            model = 'Qwen2.5-7B'
        else:
            model = 'Qwen2.5-1.5B'
    elif 'pilot' in exp_id.lower():
        model = 'Qwen2.5-1.5B'
    else:
        model = '?'

    k_star_reported = metrics.get('k_star', metrics.get('K_star', metrics.get('kstar_ci', 'N/A')))

    all_exp_data.append({
        'exp_id': exp_id,
        'hypothesis': hypothesis[:150],
        'model': model,
        'domain': domain,
        'k_star_reported': k_star_reported,
        'pairwise_auc': pairwise,
    })

# Also handle exp_020_pythia_decoding sub-experiments
exp_020 = experiments.get('exp_020_pythia_decoding', {})
if exp_020.get('conclusion') == 'success':
    m020 = exp_020.get('metrics', {})
    for setting, sdata in m020.items():
        if isinstance(sdata, dict) and 'auc' in sdata:
            auc = sdata['auc']
            if all(k in auc for k in ['0v1', '1v2', '2v3']):
                all_exp_data.append({
                    'exp_id': f'exp_020_{setting}',
                    'hypothesis': f'Pythia-1.4B decoding ablation ({setting})',
                    'model': 'Pythia-1.4B',
                    'domain': 'C4',
                    'k_star_reported': sdata.get('K_star', 'N/A'),
                    'pairwise_auc': dict(auc),
                })

# Sort: C4 first, then arXiv, then others
domain_order = {'C4': 0, 'arXiv': 1, 'Wikipedia': 2, 'Retrain-chain': 3}
all_exp_data.sort(key=lambda x: (domain_order.get(x['domain'], 99), x['exp_id']))

# Compute K* for each theta
thetas = [0.55, 0.575, 0.60, 0.625, 0.65, 0.70]
pair_sequence = ['0v1', '1v2', '2v3', '3v4', '4v5']

def compute_kstar(pairwise, theta):
    kstar = 0
    for pair in pair_sequence:
        if pair not in pairwise:
            break
        if pairwise[pair] >= theta:
            kstar += 1
        else:
            break
    return kstar

# Compute K* for all experiments and thetas
for exp in all_exp_data:
    exp['kstar_by_theta'] = {}
    for theta in thetas:
        exp['kstar_by_theta'][theta] = compute_kstar(exp['pairwise_auc'], theta)

# Print summary for verification
print(f"Total experiments for analysis: {len(all_exp_data)}")
print()
for exp in all_exp_data:
    kstars = [str(exp['kstar_by_theta'][t]) for t in thetas]
    print(f"{exp['exp_id']:40s} {exp['domain']:12s} {exp['model']:16s} K*@theta: {', '.join(kstars)}  reported={exp['k_star_reported']}")

# Save for report generation
with open('/tmp/theta_analysis.json', 'w') as f:
    json.dump(all_exp_data, f, indent=2)
PYEOF
